    31	#include "idn2.h"
    32	#include "fuzzer.h"
    33	
    34	static int flags[] = {
    35	        0,
    36	        IDN2_NFC_INPUT,
    37	        IDN2_TRANSITIONAL,
    38	        IDN2_NONTRANSITIONAL,
    39	        IDN2_TRANSITIONAL|IDN2_USE_STD3_ASCII_RULES,
    40	        IDN2_NONTRANSITIONAL|IDN2_USE_STD3_ASCII_RULES
    41	};
    42	
    43	int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    44	{
    45	        char *domain;
    46	        char *out;
    47	
    48	        if (size > 1024)
    49	                return 0;
    50	
    51	        domain = (char *) malloc(size + 1);
    52	        assert(domain != NULL);
    53	
    54	        /* 0 terminate */
    55	        memcpy(domain, data, size);
    56	        domain[size] = 0;
    57	
    58	        if (size == 0) {
    59	                /*** test NULL input/output combinations ***/
    60	
    61	                if (idn2_to_ascii_8z(NULL, &out, 0) == IDN2_OK)
    62	                        idn2_free(out);
    63	                idn2_to_ascii_8z(NULL, NULL, 0);
    64	                idn2_to_ascii_8z(domain, NULL, 0);
    65	
    66	                if (idn2_to_ascii_lz(NULL, &out, 0) == IDN2_OK)
    67	                        idn2_free(out);
    68	                idn2_to_ascii_lz(NULL, NULL, 0);
    69	                idn2_to_ascii_lz(domain, NULL, 0);
    70	
    71	                {
    72	                        uint32_t in32[1]={0};
    73	                        char out8[1];
    74	                        idn2_to_ascii_4i(NULL, 0, out8, 0);
    75	                        idn2_to_ascii_4i(NULL, 0, NULL, 0);
    76	                        idn2_to_ascii_4i(in32, 0, NULL, 0);
    77	                }
    78	
    79	                {
    80	                        uint32_t in32[1]={0};
    81	                        if (idn2_to_ascii_4i2(NULL, 0, &out, 0) == IDN2_OK)
    82	                                idn2_free(out);
    83	                        idn2_to_ascii_4i2(NULL, 0, NULL, 0);
    84	                        idn2_to_ascii_4i2(in32, 0, NULL, 0);
    85	
    86	                        if (idn2_to_ascii_4z(NULL, &out, 0) == IDN2_OK)
    87	                                idn2_free(out);
    88	                        idn2_to_ascii_4z(NULL, NULL, 0);
    89	                        idn2_to_ascii_4z(in32, NULL, 0);
    90	                }
    91	        }
    92	
    93	        for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++) {
    94	                if (idn2_to_ascii_8z(domain, &out, flags[it]) == IDN2_OK)
    95	                        idn2_free(out);
    96	                if (idn2_to_ascii_lz(domain, &out, flags[it]) == IDN2_OK)
    97	                        idn2_free(out);
    98	        }
    99	
   100	        if ((size & 3) == 0) {
   101	                uint32_t *u32 = (uint32_t *) malloc(size + 4);
   102	                char *out2 = (char *) malloc(64);
   103	
   104	                assert(u32 != NULL);
   105	                assert(out2 != NULL);
   106	
   107	                idn2_to_ascii_4i((uint32_t *) data, size / 4, out2, 0);
   108	
   109	                for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++)
   110	                        if (idn2_to_ascii_4i2((uint32_t *) data, size / 4, &out, flags[it]) == IDN2_OK)
   111	                                idn2_free(out);
   112	
   113	                memcpy(u32, data, size);
   114	                u32[size / 4] = 0;
   115	
   116	                for (unsigned it = 0; it < sizeof(flags)/sizeof(flags[0]); it++)
   117	                        if (idn2_to_ascii_4z(u32, &out, flags[it]) == IDN2_OK)
   118	                          idn2_free(out);
   119	
   120	                free(out2);
   121	                free(u32);
   122	        }
   123	
   124	        free(domain);
   125	        return 0;
   126	}
